81	std::optional<StationCatalog> LoadStationCatalog(const std::filesystem::path& path) {
82	  std::ifstream input(path);
83	  if (!input) {
84	    return std::nullopt;
85	  }
86	
87	  StationCatalog catalog;
88	  Station current_station;
89	  RoadNode current_road_node;
90	  CatalogStationEdge current_edge;
91	  std::string default_frame_id = "map";
92	  std::string section;
93	  bool in_station = false;
94	  bool in_road_node = false;
95	  bool in_edge = false;
96	  bool in_polyline = false;
97	  bool has_id = false;
98	  bool has_x = false;
99	  bool has_y = false;
100	  bool has_node_id = false;
101	  bool has_node_x = false;
102	  bool has_node_y = false;
103	  bool has_from = false;
104	  bool has_to = false;
105	  bool has_distance = false;
106	  // map 风格折线点（- x: ... / y: ...）的暂存分量
107	  std::pair<double, double> pending_point{0.0, 0.0};
108	  bool point_has_x = false;
109	  bool point_has_y = false;
110	  // 折线严格解析失败标记：半截点/坏点/未知条目一律让加载失败，
111	  // 而不是静默丢弃折线后仍报告加载成功。
112	  bool malformed = false;
113	
114	  auto flush_polyline_point = [&]() {
115	    if (point_has_x != point_has_y) {
116	      malformed = true;  // 半截点（缺 x 或缺 y）：不静默丢弃
117	    }
118	    if (point_has_x && point_has_y) {
119	      current_edge.polyline.push_back(pending_point);
120	    }
121	    pending_point = std::pair<double, double>{0.0, 0.0};
122	    point_has_x = false;
123	    point_has_y = false;
124	  };
125	
126	  auto flush_station = [&]() {
127	    if (in_station && has_id && has_x && has_y) {
128	      if (current_station.frame_id.empty()) {
129	        current_station.frame_id = default_frame_id;
130	      }
131	      catalog.stations.push_back(current_station);
132	    }
133	    current_station = Station{};
134	    current_station.frame_id = default_frame_id;
135	    in_station = false;
136	    has_id = false;
137	    has_x = false;
138	    has_y = false;
139	  };
140	
141	  auto flush_road_node = [&]() {
142	    if (in_road_node && has_node_id && has_node_x && has_node_y) {
143	      if (current_road_node.frame_id.empty()) {
144	        current_road_node.frame_id = default_frame_id;
145	      }
146	      catalog.road_nodes.push_back(current_road_node);
147	    }
148	    current_road_node = RoadNode{};
149	    current_road_node.frame_id = default_frame_id;
150	    in_road_node = false;
151	    has_node_id = false;
152	    has_node_x = false;
153	    has_node_y = false;
154	  };
155	
156	  auto flush_edge = [&]() {
157	    flush_polyline_point();
158	    if (in_edge && has_from && has_to && has_distance) {
159	      catalog.edges.push_back(current_edge);
160	    }
161	    current_edge = CatalogStationEdge{};
162	    in_edge = false;
163	    in_polyline = false;
164	    has_from = false;
165	    has_to = false;
166	    has_distance = false;
167	  };
168	
169	  std::string line;
170	  while (std::getline(input, line)) {
171	    if (malformed) {
172	      return std::nullopt;  // 折线块内已记录的非法结构：快速失败
173	    }
174	    line = Trim(line);
175	    if (line.empty() || line.front() == '#') {
176	      continue;
177	    }
178	
179	    if (line == "stations:" || line == "edges:" || line == "routes:" || line == "road_nodes:" ||
180	        line == "version:") {
181	      flush_station();
182	      flush_road_node();
183	      flush_edge();
184	      section = line.substr(0, line.size() - 1);
185	      continue;
186	    }
187	
188	    if (!in_station && !in_edge && !in_road_node) {
189	      if (auto value = ValueAfterColon(line, "frame_id")) {
190	        default_frame_id = value->empty() ? "map" : *value;
191	        current_station.frame_id = default_frame_id;
192	        current_road_node.frame_id = default_frame_id;
193	        continue;
194	      }
195	      if (auto value = ValueAfterColon(line, "map_hash")) {
196	        catalog.map_hash = *value;
197	        continue;
198	      }
199	      if (auto value = ValueAfterColon(line, "graph_version")) {
200	        catalog.graph_version = *value;
201	        continue;
202	      }
203	    }
204	
205	    if (line.rfind("- ", 0) == 0) {
206	      const std::string content = Trim(line.substr(2));
207	      if (in_polyline && !content.empty() && content.front() == '[') {
208	        // flow 风格折线点：- [x, y]；坏点（如 - [broken]）严格失败，不静默丢弃
209	        const auto point = ParseFlowPoint(content);
210	        if (!point) {
211	          return std::nullopt;
212	        }
213	        flush_polyline_point();
214	        current_edge.polyline.push_back(*point);
215	        continue;
216	      }
217	      if (in_polyline && (ValueAfterColon(content, "x") || ValueAfterColon(content, "y"))) {
218	        // map 风格折线点起始：- x: ... / - y: ...
219	        flush_polyline_point();
220	        if (auto value = ValueAfterColon(content, "x")) {
221	          const auto parsed = ParseDouble(*value);
222	          if (!parsed) {
223	            return std::nullopt;
224	          }
225	          pending_point.first = *parsed;
226	          point_has_x = true;
227	        } else if (auto value = ValueAfterColon(content, "y")) {
228	          const auto parsed = ParseDouble(*value);
229	          if (!parsed) {
230	            return std::nullopt;
231	          }
232	          pending_point.second = *parsed;
233	          point_has_y = true;
234	        }
235	        continue;
236	      }
237	      if (in_polyline) {
238	        // 折线块内既不是合法折线点、也不是已知 edge 字段/新 polyline 键的
239	        // "- " 条目（如嵌套块序列）：严格失败。此前会当成新边起点，
240	        // 把整条折线静默吞掉却仍报告加载成功。
241	        if (!IsEdgeFieldKey(content) && !ValueAfterColon(content, "polyline")) {
242	          return std::nullopt;
243	        }
244	        flush_edge();
245	        in_edge = true;
246	      } else if (section == "edges" || section == "routes") {
247	        flush_edge();
248	        in_edge = true;
249	      } else if (section == "road_nodes") {
250	        flush_road_node();
251	        in_road_node = true;
252	        current_road_node.frame_id = default_frame_id;
253	      } else {
254	        flush_station();
255	        in_station = true;
256	        current_station.frame_id = default_frame_id;
257	      }
258	      line = content;
259	    }
260	
261	    if (in_edge) {
262	      if (ValueAfterColon(line, "polyline")) {
263	        flush_polyline_point();
264	        in_polyline = true;
265	        continue;
266	      }
267	      if (in_polyline) {
268	        if (IsEdgeFieldKey(line)) {
269	          flush_polyline_point();
270	          if (malformed) {
271	            return std::nullopt;
272	          }
273	          in_polyline = false;  // 折线块结束，继续按 edge 字段解析本行
274	        } else if (auto value = ValueAfterColon(line, "x")) {
275	          if (point_has_x) {
276	            flush_polyline_point();  // 未走 "- " 的连续 x：先结算上一个点
277	          }
278	          const auto parsed = ParseDouble(*value);
279	          if (!parsed) {
280	            return std::nullopt;
281	          }
282	          pending_point.first = *parsed;
283	          point_has_x = true;
284	          continue;
285	        } else if (auto value = ValueAfterColon(line, "y")) {
286	          if (point_has_y) {
287	            flush_polyline_point();  // 未走 "- " 的连续 y：先结算上一个点
288	          }
289	          const auto parsed = ParseDouble(*value);
290	          if (!parsed) {
291	            return std::nullopt;
292	          }
293	          pending_point.second = *parsed;
294	          point_has_y = true;
295	          continue;
296	        } else {
297	          return std::nullopt;  // 折线块内未知行：严格失败，不再静默忽略
298	        }
299	      }
300	      if (auto value = ValueAfterColon(line, "from")) {
301	        current_edge.from = *value;
302	        has_from = !current_edge.from.empty();
303	        continue;
304	      }
305	      if (auto value = ValueAfterColon(line, "to")) {
306	        current_edge.to = *value;
307	        has_to = !current_edge.to.empty();
308	        continue;
309	      }
310	      if (auto value = ValueAfterColon(line, "distance_m")) {
311	        if (auto parsed = ParseDouble(*value)) {
312	          current_edge.distance_m = *parsed;
313	          has_distance = true;
314	        }
315	        continue;
316	      }
317	      if (auto value = ValueAfterColon(line, "distance")) {
318	        if (auto parsed = ParseDouble(*value)) {
319	          current_edge.distance_m = *parsed;
320	          has_distance = true;
321	        }
322	        continue;
323	      }
324	      if (auto value = ValueAfterColon(line, "bidirectional")) {
325	        current_edge.bidirectional = ParseBool(*value);
326	        continue;
327	      }
328	      if (auto value = ValueAfterColon(line, "enabled")) {
329	        current_edge.enabled = ParseBool(*value);
330	        continue;
331	      }
332	      continue;
333	    }
334	
335	    if (in_road_node) {
336	      if (auto value = ValueAfterColon(line, "id")) {
337	        current_road_node.id = *value;
338	        has_node_id = !current_road_node.id.empty();
339	        continue;
340	      }
341	      if (auto value = ValueAfterColon(line, "frame_id")) {
342	        current_road_node.frame_id = value->empty() ? default_frame_id : *value;
343	        continue;
344	      }
345	      if (auto value = ValueAfterColon(line, "x")) {
346	        if (auto parsed = ParseDouble(*value)) {
347	          current_road_node.x = *parsed;
348	          has_node_x = true;
349	        }
350	        continue;
351	      }
352	      if (auto value = ValueAfterColon(line, "y")) {
353	        if (auto parsed = ParseDouble(*value)) {
354	          current_road_node.y = *parsed;
355	          has_node_y = true;
356	        }
357	        continue;
358	      }
359	      if (auto value = ValueAfterColon(line, "yaw")) {
360	        if (auto parsed = ParseDouble(*value)) {
361	          current_road_node.yaw = *parsed;
362	        }
363	        continue;
364	      }
365	      continue;  // road_nodes 条目内的其他字段（如 type）忽略
366	    }
367	
368	    if (auto value = ValueAfterColon(line, "id")) {
369	      current_station.id = *value;
370	      has_id = !current_station.id.empty();
371	      continue;
372	    }
373	    if (auto value = ValueAfterColon(line, "frame_id")) {
374	      current_station.frame_id = value->empty() ? default_frame_id : *value;
375	      continue;
376	    }
377	    if (auto value = ValueAfterColon(line, "x")) {
378	      if (auto parsed = ParseDouble(*value)) {
379	        current_station.x = *parsed;
380	        has_x = true;
381	      }
382	      continue;
383	    }
384	    if (auto value = ValueAfterColon(line, "y")) {
385	      if (auto parsed = ParseDouble(*value)) {
386	        current_station.y = *parsed;
387	        has_y = true;
388	      }
389	      continue;
390	    }
391	    if (auto value = ValueAfterColon(line, "yaw")) {
392	      if (auto parsed = ParseDouble(*value)) {
393	        current_station.yaw = *parsed;
394	      }
395	      continue;
396	    }
397	  }
398	  flush_station();
399	  flush_road_node();
400	  flush_edge();
401	  if (malformed) {
402	    return std::nullopt;  // 文件末尾结算时发现半截折线点
403	  }
404	
405	  std::string message;
406	  if (!ValidateStationCatalog(catalog, &message)) {
407	    return std::nullopt;
408	  }
409	  return catalog;
410	}
411	
412	const Station* FindStation(const StationCatalog& catalog, const std::string& id) {
413	  for (const auto& station : catalog.stations) {
414	    if (station.id == id) {
415	      return &station;
416	    }
417	  }
418	  return nullptr;
419	}
420	
421	std::optional<double> EstimateRouteDistance(
422	    const StationCatalog& catalog, const std::string& from, const std::string& to) {
423	  const auto path = FindRoutePath(catalog, from, to);
424	  if (!path.has_value()) {
425	    return std::nullopt;
426	  }
427	  double distance_m = 0.0;
428	  for (std::size_t index = 1; index < path->size(); ++index) {
429	    for (const auto& edge : catalog.edges) {
430	      const bool forward = edge.from == (*path)[index - 1] && edge.to == (*path)[index];
431	      const bool reverse =
432	          edge.bidirectional && edge.to == (*path)[index - 1] && edge.from == (*path)[index];
433	      if (edge.enabled && (forward || reverse)) {
434	        distance_m += edge.distance_m;
435	        break;
436	      }
437	    }
438	  }
439	  return distance_m;
440	}
441	
442	std::optional<std::vector<std::string>> FindRoutePath(
443	    const StationCatalog& catalog, const std::string& from, const std::string& to) {
444	  if (from == to) {
445	    return std::vector<std::string>{from};
446	  }
447	
448	  std::vector<std::string> ids;
449	  ids.reserve(catalog.stations.size() + catalog.road_nodes.size());
450	  for (const auto& station : catalog.stations) {
451	    ids.push_back(station.id);
452	  }
453	  // 通行节点与站点共用同一图节点集合，支持途经路口的混合图寻路
454	  for (const auto& road_node : catalog.road_nodes) {
455	    ids.push_back(road_node.id);
456	  }
457	  const auto index_of = [&](const std::string& id) -> std::optional<std::size_t> {
458	    const auto it = std::find(ids.begin(), ids.end(), id);
459	    if (it == ids.end()) {
460	      return std::nullopt;
461	    }
462	    return static_cast<std::size_t>(std::distance(ids.begin(), it));
463	  };
464	
465	  const auto start = index_of(from);
466	  const auto goal = index_of(to);
467	  if (!start.has_value() || !goal.has_value()) {
468	    return std::nullopt;
469	  }
470	
471	  const double infinity = std::numeric_limits<double>::infinity();
472	  std::vector<double> distance(ids.size(), infinity);
473	  std::vector<std::optional<std::size_t>> previous(ids.size(), std::nullopt);
474	  std::vector<bool> visited(ids.size(), false);
475	  distance[*start] = 0.0;
476	
477	  for (std::size_t iteration = 0; iteration < ids.size(); ++iteration) {
478	    std::optional<std::size_t> current;
479	    for (std::size_t i = 0; i < ids.size(); ++i) {
480	      if (!visited[i] && (!current.has_value() || distance[i] < distance[*current])) {
481	        current = i;
482	      }
483	    }
484	    if (!current.has_value() || !std::isfinite(distance[*current])) {
485	      break;
486	    }
487	    if (*current == *goal) {
488	      break;
489	    }
490	    visited[*current] = true;
491	
492	    for (const auto& edge : catalog.edges) {
493	      if (!edge.enabled) {
494	        continue;
495	      }
496	      const auto edge_from = index_of(edge.from);
497	      const auto edge_to = index_of(edge.to);
498	      if (!edge_from.has_value() || !edge_to.has_value()) {
499	        continue;
500	      }
501	      auto relax = [&](const std::size_t source, const std::size_t target) {
502	        if (source == *current && distance[source] + edge.distance_m < distance[target]) {
503	          distance[target] = distance[source] + edge.distance_m;
504	          previous[target] = source;
505	        }
506	      };
507	      relax(*edge_from, *edge_to);
508	      if (edge.bidirectional) {
509	        relax(*edge_to, *edge_from);
510	      }
511	    }
512	  }
513	  if (!std::isfinite(distance[*goal])) {
514	    return std::nullopt;
515	  }
516	  std::vector<std::string> path;
517	  for (auto current = *goal;;) {
518	    path.push_back(ids[current]);
519	    if (current == *start) {
520	      break;
521	    }
522	    if (!previous[current].has_value()) {
523	      return std::nullopt;
524	    }
525	    current = *previous[current];
526	  }
527	  std::reverse(path.begin(), path.end());
528	  return path;
529	}
