694	void StationCatalogReloader::TryLoad(bool count_as_reload) {
695	  if (auto loaded = LoadStationCatalog(path_)) {
696	    catalog_ = std::move(*loaded);
697	    loaded_ = true;
698	    if (count_as_reload) {
699	      ++reload_count_;
700	    }
701	    last_error_.clear();
702	  } else {
703	    // 校验失败（空目录、重复 id、非法位姿等）：保留旧目录，记录错误
704	    last_error_ = "station catalog invalid or unreadable: " + path_.string();
705	  }
