1	#include "amr_dispatcher_core/planning/skeleton_extractor.hpp"
2	
3	#include <cstddef>
4	#include <cstdint>
5	#include <utility>
6	#include <vector>
7	
8	namespace amr_dispatcher_core::planning {
9	namespace {
10	
11	// 8 邻域方向（顺时针，自正北起）：N, NE, E, SE, S, SW, W, NW。
12	// Zhang-Suen 的 P2..P9 与剪枝的度数统计共用这一顺序。
13	constexpr int kDRow[8] = {-1, -1, 0, 1, 1, 1, 0, -1};
14	constexpr int kDCol[8] = {0, 1, 1, 1, 0, -1, -1, -1};
15	
16	// 受保护判定的欧式距离阈值（像素）：站点停靠位通常经正交投影落在骨架
17	// 附近，1.5 像素（默认 0.075m）容差足以吸收亚像素舍入。
18	constexpr double kProtectedDistancePx = 1.5;
19	
20	// 对角步长：分支推进时用于把 8 方向步向量归一化，比较与来向的夹角余弦。
21	constexpr double kSqrt2 = 1.41421356237309504880;
22	
23	// 骨架像素坐标（整数栅格）。
24	struct Pixel {
25	  int col = 0;
26	  int row = 0;
27	};
28	
29	// 8 邻域内相邻骨架像素数，即剪枝算法中的"度数"。
30	int Degree(const BinaryGrid& grid, int col, int row) {
31	  int count = 0;
32	  for (int i = 0; i < 8; ++i) {
33	    if (grid.GetValue(col + kDCol[i], row + kDRow[i])) {
34	      ++count;
35	    }
36	  }
37	  return count;
38	}
39	
40	// 8 邻域环上的连通组数（P2..P9,P2 环状序列中 0→1 跳变次数）：
41	//   0 = 无邻居，1 = 端点 / 单组，2 = 线段点，>= 3 = 分叉点。
42	// 与裸度数相比，组数不会把"紧邻正交交叉点的直线像素"（其度数也 >= 3）
43	// 误判为分叉，是像素骨架上更稳健的分叉判据。
44	int CrossingNumber(const BinaryGrid& grid, int col, int row) {
45	  int neighbors[8];
46	  int B = 0;
47	  for (int i = 0; i < 8; ++i) {
48	    neighbors[i] = grid.GetValue(col + kDCol[i], row + kDRow[i]) ? 1 : 0;
49	    B += neighbors[i];
50	  }
51	  if (B == 0) {
52	    return 0;
53	  }
54	  if (B == 8) {
55	    return 1;  // 完全被包围：单一连通组（防御分支，1 像素宽骨架不会出现）
56	  }
57	  int groups = 0;
58	  for (int i = 0; i < 8; ++i) {
59	    if (!neighbors[i] && neighbors[(i + 1) % 8]) {
60	      ++groups;
61	    }
62	  }
63	  return groups;
64	}
65	
66	// 剪除分支后，停止点 S 的剩余邻居在 4 邻接（网格意义）下是否构成单一
67	// 连通组。成立时说明 S 仅因被剪掉的分支而呈现为"分叉"——本体是主线上的
68	// 冗余凸起像素（1 像素宽骨架的正交 T 接合处常见），若不一并剪除会在主干
69	// 上留下 1 像素毛刺伪影。真正的 Y / T / 十字分叉点剩余邻居彼此不相邻，
70	// 返回 false 得以保留。
71	bool NeighborsSingleFourConnected(const BinaryGrid& grid, int col, int row) {
72	  std::vector<Pixel> neighbors;
73	  for (int i = 0; i < 8; ++i) {
74	    if (grid.GetValue(col + kDCol[i], row + kDRow[i])) {
75	      neighbors.push_back({col + kDCol[i], row + kDRow[i]});
76	    }
77	  }
78	  if (neighbors.size() <= 1) {
79	    return true;
80	  }
81	  // 在邻居像素集合上做 4 邻接连通性 BFS。
82	  std::vector<uint8_t> visited(neighbors.size(), 0);
83	  std::vector<size_t> stack{0};
84	  visited[0] = 1;
85	  size_t reached = 1;
86	  while (!stack.empty()) {
87	    const size_t index = stack.back();
88	    stack.pop_back();
89	    for (size_t j = 0; j < neighbors.size(); ++j) {
90	      if (visited[j]) {
91	        continue;
92	      }
93	      const int dc = neighbors[index].col - neighbors[j].col;
94	      const int dr = neighbors[index].row - neighbors[j].row;
95	      if ((dc == 0 && (dr == 1 || dr == -1)) ||
96	          (dr == 0 && (dc == 1 || dc == -1))) {
97	        visited[j] = 1;
98	        stack.push_back(j);
99	        ++reached;
100	      }
101	    }
102	  }
103	  return reached == neighbors.size();
104	}
105	
106	// 分支是否受保护：任一像素与某保护点欧式距离 < 1.5 像素即豁免。
107	bool IsProtectedBranch(const std::vector<Pixel>& branch,
108	                       const std::vector<PixelCoord>& protected_points) {
109	  for (const Pixel& pixel : branch) {
110	    for (const PixelCoord& point : protected_points) {
111	      const double d_col = static_cast<double>(pixel.col) - point.col;
112	      const double d_row = static_cast<double>(pixel.row) - point.row;
113	      if (d_col * d_col + d_row * d_row <
114	          kProtectedDistancePx * kProtectedDistancePx) {
115	        return true;
116	      }
117	    }
118	  }
119	  return false;
120	}
121	
122	}  // namespace
123	
124	BinaryGrid ZhangSuenThinning(const BinaryGrid& grid) {
125	  BinaryGrid result = grid;
126	  if (result.width == 0 || result.height == 0) {
127	    return result;
128	  }
129	
130	  bool changed = true;
131	  while (changed) {
132	    changed = false;
133	    for (int step = 0; step < 2; ++step) {
134	      // 先收集本轮待删除像素，再统一置 0 —— 保证子步内所有判定基于同一
135	      // 快照（Zhang-Suen 的标准同步语义）。
136	      std::vector<Pixel> to_remove;
137	      for (uint32_t row = 0; row < result.height; ++row) {
138	        for (uint32_t col = 0; col < result.width; ++col) {
139	          const int c = static_cast<int>(col);
140	          const int r = static_cast<int>(row);
141	          if (!result.GetValue(c, r)) {
142	            continue;
143	          }
144	          // P2..P9（自正北顺时针），B 为邻域内骨架像素总数。
145	          int neighbors[8];
146	          int B = 0;
147	          for (int i = 0; i < 8; ++i) {
148	            neighbors[i] = result.GetValue(c + kDCol[i], r + kDRow[i]) ? 1 : 0;
149	            B += neighbors[i];
150	          }
151	          if (B < 2 || B > 6) {
152	            continue;  // 孤立点与骨架内部点均不删除
153	          }
154	          // A：P2..P9,P2 环状序列中 0→1 跳变次数，==1 保证不切断连通性。
155	          int A = 0;
156	          for (int i = 0; i < 8; ++i) {
157	            if (!neighbors[i] && neighbors[(i + 1) % 8]) {
158	              ++A;
159	            }
160	          }
161	          if (A != 1) {
162	            continue;
163	          }
164	          bool condition = false;
165	          if (step == 0) {
166	            // 子步 1：P2*P4*P6 == 0 且 P4*P6*P8 == 0
167	            condition = (neighbors[0] * neighbors[2] * neighbors[4] == 0) &&
168	                        (neighbors[2] * neighbors[4] * neighbors[6] == 0);
169	          } else {
170	            // 子步 2：P2*P4*P8 == 0 且 P2*P6*P8 == 0
171	            condition = (neighbors[0] * neighbors[2] * neighbors[6] == 0) &&
172	                        (neighbors[0] * neighbors[4] * neighbors[6] == 0);
173	          }
174	          if (condition) {
175	            to_remove.push_back({c, r});
176	          }
177	        }
178	      }
179	      if (!to_remove.empty()) {
180	        changed = true;
181	        for (const Pixel& pixel : to_remove) {
182	          result.SetValue(pixel.col, pixel.row, 0);
183	        }
184	      }
185	    }
186	  }
187	  return result;
188	}
189	
190	BinaryGrid PruneSkeletonProtected(const BinaryGrid& skeleton,
191	                                  const std::vector<PixelCoord>& protected_points,
192	                                  const PruneConfig& config) {
193	  BinaryGrid result = skeleton;
194	  if (result.width == 0 || result.height == 0) {
195	    return result;
196	  }
197	  const double resolution = config.resolution > 0.0 ? config.resolution : 0.05;
198	
199	  bool changed = true;
200	  while (changed) {
201	    changed = false;
202	    // 每轮重新扫描端点：上一轮剪除会改变度数，端点集合随之变化。
203	    for (uint32_t row = 0; row < result.height; ++row) {
204	      for (uint32_t col = 0; col < result.width; ++col) {
205	        const int start_col = static_cast<int>(col);
206	        const int start_row = static_cast<int>(row);
207	        // 端点在处理时即时复核：同一轮里它可能已被先前的剪除删除。
208	        if (!result.GetValue(start_col, start_row) ||
209	            Degree(result, start_col, start_row) != 1) {
210	          continue;
211	        }
212	
213	        // 从端点向内追踪分支：visited 记录分支像素（端点起，不含停止点）。
214	        std::vector<Pixel> visited;
215	        visited.push_back({start_col, start_row});
216	        int prev_col = start_col;
217	        int prev_row = start_row;
218	        // 端点唯一的骨架邻居即为追踪方向。
219	        int cur_col = -1;
220	        int cur_row = -1;
221	        for (int i = 0; i < 8; ++i) {
222	          const int ncol = start_col + kDCol[i];
223	          const int nrow = start_row + kDRow[i];
224	          if (result.GetValue(ncol, nrow)) {
225	            cur_col = ncol;
226	            cur_row = nrow;
227	            break;
228	          }
229	        }
230	
231	        bool reached_junction = false;
232	        bool reached_other_end = false;
233	        const size_t max_steps =
234	            static_cast<size_t>(result.width) * result.height + 1;
235	        while (visited.size() <= max_steps) {
236	          // 分叉判据用连通组数而非裸度数：紧邻正交交叉点的直线像素（如 T
237	          // 接合处主干上的 (15,3)）8 邻域裸度数也 >= 3，若按裸度数判定
238	          // 会在剪除后于主干上残留 1 像素凸起伪影。
239	          const int crossings = CrossingNumber(result, cur_col, cur_row);
240	          if (crossings >= 3) {
241	            reached_junction = true;
242	            break;
243	          }
244	          if (crossings <= 1) {
245	            // 追踪到另一个端点：整条线段无分叉锚点（例如孤立短线段），
246	            // 不属于"死胡同毛刺"，跳过不剪，避免误删整个连通分量。
247	            reached_other_end = true;
248	            break;
249	          }
250	          // 连通组数 == 2：分支中段，沿与来向最接近的方向推进。
251	          // 固定环序（N,NE,E,SE,S,SW,W,NW）会把"斜向紧邻的旁侧结构"排在
252	          // 直线延续之前（如垂直毛刺基座像素的 SE 邻居先于 S 被考察），导致
253	          // 追踪横向逃逸到相邻主线：毛刺因此漏剪，或整段主线被误当分支剪
254	          // 除。改为：
255	          //   1. 优先推进到本身即分叉（连通组数 >= 3）的候选 —— 命中分叉
256	          //      立即停止追踪（分支不含分叉点）；
257	          //   2. 其余候选中选与来向 (cur - prev) 夹角最小者（归一化点积最
258	          //      大），即直线延续优先于斜向逃逸。
259	          visited.push_back({cur_col, cur_row});
260	          const int dir_col = cur_col - prev_col;
261	          const int dir_row = cur_row - prev_row;
262	          int next_col = -1;
263	          int next_row = -1;
264	          bool next_is_junction = false;
265	          double next_best_cos = -2.0;
266	          for (int i = 0; i < 8; ++i) {
267	            const int ncol = cur_col + kDCol[i];
268	            const int nrow = cur_row + kDRow[i];
269	            if ((ncol == prev_col && nrow == prev_row) ||
270	                !result.GetValue(ncol, nrow)) {
271	              continue;
272	            }
273	            const int step_col = ncol - cur_col;
274	            const int step_row = nrow - cur_row;
275	            // |dir| 对所有候选为公共因子，比较 cos 时可省略；仅归一化步长。
276	            const double step_len =
277	                (step_col == 0 || step_row == 0) ? 1.0 : kSqrt2;
278	            const double cos_angle =
279	                (dir_col * step_col + dir_row * step_row) / step_len;
280	            const bool is_junction = CrossingNumber(result, ncol, nrow) >= 3;
281	            if (next_col == -1 || (is_junction && !next_is_junction) ||
282	                (is_junction == next_is_junction &&
283	                 cos_angle > next_best_cos)) {
284	              next_col = ncol;
285	              next_row = nrow;
286	              next_is_junction = is_junction;
287	              next_best_cos = cos_angle;
288	            }
289	          }
290	          if (next_col == -1) {
291	            break;  // 防御：连通组数 == 2 必有非来向邻居，不应发生。
292	          }
293	          prev_col = cur_col;
294	          prev_row = cur_row;
295	          cur_col = next_col;
296	          cur_row = next_row;
297	        }
298	        if (!reached_junction || reached_other_end) {
299	          continue;
300	        }
301	
302	        const double branch_length_m =
303	            static_cast<double>(visited.size()) * resolution;
304	        if (!(branch_length_m < config.min_branch_length_m)) {
305	          continue;  // 长分支保留
306	        }
307	        // 受保护分支（承载站点）强制豁免，不可剪除。
308	        if (IsProtectedBranch(visited, protected_points)) {
309	          continue;
310	        }
311	        // 剪除短毛刺：分支像素全部置 0，分叉点保留。
312	        for (const Pixel& pixel : visited) {
313	          result.SetValue(pixel.col, pixel.row, 0);
314	        }
315	        // 冗余停止点清理：T 接合处，停止点 S 常因被剪分支才呈现为"分叉"
316	        // （其邻居经 4 邻接连通后实为主干线的一段）。分支剪除后 S 的剩余
317	        // 邻居若构成单一连通组，S 即为主干上的冗余凸起，一并剪除以免留
318	        // 下 1 像素伪影；真正的 Y / T / 十字分叉点剩余邻居彼此不相邻，
319	        // 得以保留。受保护点附近的停止点同样豁免。
320	        if (!IsProtectedBranch({{cur_col, cur_row}}, protected_points) &&
321	            NeighborsSingleFourConnected(result, cur_col, cur_row)) {
322	          result.SetValue(cur_col, cur_row, 0);
323	        }
324	        changed = true;
325	      }
326	    }
327	  }
328	  return result;
329	}
