50	BinaryGrid FilterSafetySpace(const MapGrid& grid,
51	                             const SafetyFilterConfig& config) {
52	  BinaryGrid result;
53	  result.width = grid.width;
54	  result.height = grid.height;
55	  const size_t total = static_cast<size_t>(grid.width) *
56	                       static_cast<size_t>(grid.height);
57	  result.data.assign(total, 1);  // 默认：通行候选
58	
59	  // ---- 第一步：二值标记（占用 / 未知 -> 初始障碍），同时收集障碍点 ----
60	  std::vector<std::pair<int, int>> obstacles;
61	  obstacles.reserve(total / 8);
62	  for (uint32_t row = 0; row < grid.height; ++row) {
63	    for (uint32_t col = 0; col < grid.width; ++col) {
64	      // GetValue 对越界或未初始化数据防御性返回 -1（未知），
65	      // 未知是否视为障碍由 treat_unknown_as_obstacle 决定。
66	      const int8_t value = grid.GetValue(static_cast<int>(col),
67	                                         static_cast<int>(row));
68	      const bool is_obstacle =
69	          value >= config.occupied_threshold ||
70	          (config.treat_unknown_as_obstacle && value < 0);
71	      if (is_obstacle) {
72	        result.data[CellIndex(result.width, static_cast<int>(col),
73	                              static_cast<int>(row))] = 0;
74	        obstacles.emplace_back(static_cast<int>(col),
75	                               static_cast<int>(row));
76	      }
77	    }
78	  }
79	
80	  // ---- 第二步：圆形核膨胀（等价于可通行区欧式距离腐蚀） ----
81	  const double radius = config.robot_radius_m + config.safety_margin_m;
82	  const double resolution = grid.resolution;
83	  if (radius <= 0.0 || resolution <= 0.0 || obstacles.empty()) {
84	    return result;  // 无需膨胀
85	  }
86	  const int r_pix = static_cast<int>(std::ceil(radius / resolution));
87	  if (r_pix == 0) {
88	    return result;
89	  }
90	
91	  // 预计算圆形核偏移：所有满足 hypot(dx*res, dy*res) <= R 的窗口偏移。
92	  std::vector<std::pair<int, int>> kernel_offsets;
93	  kernel_offsets.reserve(static_cast<size_t>(2 * r_pix + 1) *
94	                         static_cast<size_t>(2 * r_pix + 1));
95	  const double tolerance = radius + kDistanceTolerance;
96	  for (int dy = -r_pix; dy <= r_pix; ++dy) {
97	    for (int dx = -r_pix; dx <= r_pix; ++dx) {
98	      const double dist_m =
99	          std::hypot(static_cast<double>(dx) * resolution,
100	                     static_cast<double>(dy) * resolution);
101	      if (dist_m <= tolerance) {
102	        kernel_offsets.emplace_back(dx, dy);
103	      }
104	    }
105	  }
106	
107	  // 对每个初始障碍，在其 R 半径窗口内把所有可达像素置 0。
108	  for (const auto& obstacle : obstacles) {
109	    const int obstacle_col = obstacle.first;
110	    const int obstacle_row = obstacle.second;
111	    for (const auto& offset : kernel_offsets) {
112	      const int col = obstacle_col + offset.first;
113	      const int row = obstacle_row + offset.second;
114	      if (result.IsValidPixel(col, row)) {
115	        result.data[CellIndex(result.width, col, row)] = 0;
116	      }
117	    }
118	  }
119	  return result;
120	}
121	
122	}  // namespace amr_dispatcher_core::planning
