  BinaryGrid grid;
  grid.width = width;
  grid.height = height;
  grid.data.assign(static_cast<size_t>(width) * static_cast<size_t>(height), 0);
  return grid;
}

// 在世界坐标 (x, y) 处构造一个站点。
