// 提取所有骨架特征点（crossing != 2 的像素）。返回特征点集合。
std::vector<Pixel> ExtractFeaturePixels(const BinaryGrid& skeleton) {
  std::vector<Pixel> features;
  for (uint32_t row = 0; row < skeleton.height; ++row) {
    for (uint32_t col = 0; col < skeleton.width; ++col) {
      const int c = static_cast<int>(col);
      const int r = static_cast<int>(row);
      if (!skeleton.GetValue(c, r)) {
        continue;
      }
      const int crossings = CrossingNumber(skeleton, c, r);
      if (crossings != 2) {
        features.push_back({c, r});
      }
    }
  }
  return features;
}

// 从 start_pixel 出发沿骨架追踪到下一个特征点，返回途经的像素序列
// （含起点与终点），若找不到特征点（如闭合环）则返回空序列。
// visited_edge_pixels 用来避免重复追踪同一条边——记录已访问的"中间像素"
// （crossing == 2 的非特征骨架像素）。特征点不放进该集合，允许作为多条边
// 的端点重复出现。
std::vector<Pixel> TraceChain(
    const BinaryGrid& skeleton, const Pixel& start,
    const std::unordered_set<Pixel, PixelHash>& feature_set,
    std::unordered_set<Pixel, PixelHash>* visited_middle) {
  std::vector<Pixel> chain;
  chain.push_back(start);

  // 起点本身的骨架邻居（特征点的所有 8 邻域骨架像素都是候选出发点）。
  std::vector<Pixel> start_neighbors;
  for (int i = 0; i < 8; ++i) {
    const Pixel nb{start.col + kDCol[i], start.row + kDRow[i]};
    if (skeleton.GetValue(nb.col, nb.row)) {
      start_neighbors.push_back(nb);
    }
  }
  if (start_neighbors.empty()) {
    return chain;  // 孤立点
  }

  // 从每个邻居方向分别追踪：每个方向产生一条独立的边。
  // 注意：这里返回的是"从 start 出发的一组链"的第一条，由调用方循环
  // 调度其他邻居。简化做法：本函数只追踪单一邻居方向，由外层驱动。
  // （函数签名只暴露单链追踪）
  return chain;  // 占位（实际由 TraceAllEdgesFrom 调用单步推进）
}

