// 在骨架上找到 id 为 station_id 的 Station 索引，未找到返回 -1。
int StationIndex(const catalog::StationCatalog& catalog,
                 const std::string& station_id) {
  for (size_t i = 0; i < catalog.stations.size(); ++i) {
    if (catalog.stations[i].id == station_id) {
      return static_cast<int>(i);
    }
  }
  return -1;
}

// 查找图中端点为 (a,b) 的边（无向比较）。命中返回索引，未命中返回 -1。
int FindEdgeIndex(const catalog::StationCatalog& catalog, const std::string& a,
                  const std::string& b) {
  for (size_t i = 0; i < catalog.edges.size(); ++i) {
    const auto& e = catalog.edges[i];
    if ((e.from == a && e.to == b) || (e.from == b && e.to == a)) {
      return static_cast<int>(i);
    }
  }
  return -1;
}

