#include "amr_dispatcher_core/planning/topology_graph_builder.hpp"

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <string>
#include <vector>

namespace amr_dispatcher_core::planning {
namespace {

constexpr double kResolution = 0.05;  // 米/像素

MapGrid MakeMapInfo(uint32_t width, uint32_t height, double resolution) {
  MapGrid grid;
  grid.width = width;
  grid.height = height;
  grid.resolution = resolution;
  grid.origin_x = 0.0;
  grid.origin_y = 0.0;
  grid.origin_yaw = 0.0;
  grid.data.assign(static_cast<size_t>(width) * static_cast<size_t>(height),
                   kCellFree);
  return grid;
}

BinaryGrid MakeSkeleton(uint32_t width, uint32_t height) {
  BinaryGrid grid;
  grid.width = width;
  grid.height = height;
  grid.data.assign(static_cast<size_t>(width) * static_cast<size_t>(height), 0);
  return grid;
}

// 在世界坐标 (x, y) 处构造一个站点。
AnchorStation MakeAnchor(const std::string& id, double x, double y,
                         const std::string& type = "normal") {
  AnchorStation a;
  a.id = id;
  a.x = x;
  a.y = y;
  a.type = type;
  return a;
}

// 沿 (col0,row) -> (col1,row) 填充水平骨架线。
void DrawHLine(BinaryGrid& grid, int row, int col0, int col1) {
  for (int col = col0; col <= col1; ++col) {
    grid.SetValue(col, row, 1);
  }
}

// 沿 (col,row0) -> (col,row1) 填充垂直骨架线。
void DrawVLine(BinaryGrid& grid, int col, int row0, int row1) {
  for (int row = row0; row <= row1; ++row) {
    grid.SetValue(col, row, 1);
  }
}

// 在骨架上找到 id 为 station_id 的 Station 索引，未找到返回 -1。
int StationIndex(const catalog::StationCatalog& catalog,
                 const std::string& station_id) {
  for (size_t i = 0; i < catalog.stations.size(); ++i) {
    if (catalog.stations[i].id == station_id) {
      return static_cast<int>(i);
    }
  }
  return -1;
}

// ---------------------------------------------------------------------------
// 用例 1：直走廊 + 两端站点
//   骨架：一行 20 像素直线。两端各有一个站点。断言产生 2 个站点，原边被拆
//   分为 2 条子边（或者通过 road_node 中转），FindRoutePath 可寻路。
// ---------------------------------------------------------------------------
TEST(TopologyGraphBuilderTest,
     StraightCorridor_EndpointStations_Reachable) {
  // 像素宽度 20 -> 1.0m。骨架直线 row=5，col 0..19。
  const MapGrid map_info = MakeMapInfo(20, 11, kResolution);
  BinaryGrid skeleton = MakeSkeleton(20, 11);
  DrawHLine(skeleton, 5, 0, 19);

  // 站点放在骨架两端附近（在 max_snap_dist 内）。
  std::vector<AnchorStation> anchors;
  anchors.push_back(MakeAnchor("s_left", 0.025, 0.275));   // 近 (0,5)
  anchors.push_back(MakeAnchor("s_right", 0.975, 0.275));  // 近 (19,5)

  TopologyBuilderConfig config;
  config.max_snap_dist_m = 2.0;
  config.map_hash = "test_hash_1";
  config.graph_version = "v1";

  const TopologyBuildResult result =
      BuildTopologyCatalog(skeleton, map_info, anchors, config);

  ASSERT_TRUE(result.success) << result.error_message;
  ASSERT_EQ(result.catalog.stations.size(), 2u);
  EXPECT_EQ(result.catalog.map_hash, "test_hash_1");
  EXPECT_EQ(result.catalog.graph_version, "v1");

  // 两个站点之间存在可达路径（直线上经过拆分后的中间 road_node）。
  const auto path = catalog::FindRoutePath(result.catalog, "s_left", "s_right");
  ASSERT_TRUE(path.has_value()) << "两站点之间必须可达";

  // 路径上的边应携带 polyline 折线（至少一条边应有 >=2 折线点）。
  bool any_polyline = false;
  for (const auto& edge : result.catalog.edges) {
    if (edge.polyline.size() >= 2) {
      any_polyline = true;
      break;
    }
  }
  EXPECT_TRUE(any_polyline) << "至少一条边应保留骨架折线";
}

// ---------------------------------------------------------------------------
// 用例 2：L 弯走廊 + 中段充电桩站点
//   骨架 L 形：水平段 (0,10)->(39,10) + 垂直段 (39,10)->(39,30)。
//   拐角 (39,10) 处应产生 road_node；水平段中段的充电桩站点吸附后原边拆分。
// ---------------------------------------------------------------------------
TEST(TopologyGraphBuilderTest,
     LCornerCorridor_ChargeStationSplitsEdge) {
  const MapGrid map_info = MakeMapInfo(40, 31, kResolution);
  BinaryGrid skeleton = MakeSkeleton(40, 31);
  DrawHLine(skeleton, 10, 0, 39);
  DrawVLine(skeleton, 39, 10, 30);

  // 充电桩站点位于水平段中段 (20,10) 附近（世界 y = (10+0.5)*0.05 = 0.525）。
  std::vector<AnchorStation> anchors;
  anchors.push_back(MakeAnchor("s_end_a", 0.025, 0.525));    // 水平端
  anchors.push_back(MakeAnchor("s_end_b", 1.975, 1.525));    // 垂直端 (39,30)
  anchors.push_back(MakeAnchor("charge_1", 1.025, 0.525, "charge"));  // (20,10)

  TopologyBuilderConfig config;
  config.max_snap_dist_m = 2.0;
  config.map_hash = "test_hash_2";
  config.graph_version = "v1";

  const TopologyBuildResult result =
      BuildTopologyCatalog(skeleton, map_info, anchors, config);

  ASSERT_TRUE(result.success) << result.error_message;
  ASSERT_EQ(result.catalog.stations.size(), 3u);

  // 充电桩应作为图节点。
  const int charge_idx = StationIndex(result.catalog, "charge_1");
  ASSERT_GE(charge_idx, 0) << "charge_1 必须存在于 stations 中";

  // 原"水平长边"必须被 charge_1 拆分为两段——即不存在跨越整个水平臂的边。
  // 即 s_end_a 与拐角 road_node 之间不存在直接边（必须经过 charge_1）。
  // 找一个含 "charge_1" 的边（连接 charge_1 到左侧或拐角）。
  bool edge_via_charge = false;
  for (const auto& edge : result.catalog.edges) {
    if (edge.from == "charge_1" || edge.to == "charge_1") {
      edge_via_charge = true;
      break;
    }
  }
  EXPECT_TRUE(edge_via_charge) << "应存在以 charge_1 为端点的边";

  // 全部站点间可达。
  const auto path_ab =
      catalog::FindRoutePath(result.catalog, "s_end_a", "s_end_b");
  ASSERT_TRUE(path_ab.has_value());
  const auto path_ac =
      catalog::FindRoutePath(result.catalog, "s_end_a", "charge_1");
  ASSERT_TRUE(path_ac.has_value());
  const auto path_bc =
      catalog::FindRoutePath(result.catalog, "charge_1", "s_end_b");
  ASSERT_TRUE(path_bc.has_value());

  // charge_1 -> s_end_b 路径必须途经拐角（polyline 应呈 L 形）。
  // 找一条以 charge_1 为端点的边，要求其 polyline 中存在 y 接近 0.525
  // 的拐点（拐角 (39,10) -> 世界 (1.975, 0.525)）。
  bool found_L_shape = false;
  for (const auto& edge : result.catalog.edges) {
    if (edge.polyline.size() < 3) {
      continue;
    }
    // L 形折线：拐角点应在折线中间而非首尾。
    for (size_t i = 1; i + 1 < edge.polyline.size(); ++i) {
      const auto& p = edge.polyline[i];
      if (std::abs(p.first - 1.975) < 0.05 &&
          std::abs(p.second - 0.525) < 0.05) {
        found_L_shape = true;
        break;
      }
    }
    if (found_L_shape) break;
  }
  EXPECT_TRUE(found_L_shape)
      << "L 形折线应在中间包含拐角点 (~1.975, 0.525)";
}

// ---------------------------------------------------------------------------
// 用例 3：站点距骨架过远 -> 构建失败
// ---------------------------------------------------------------------------
TEST(TopologyGraphBuilderTest, FarStation_BuildFails) {
  const MapGrid map_info = MakeMapInfo(20, 20, kResolution);
  BinaryGrid skeleton = MakeSkeleton(20, 20);
  DrawHLine(skeleton, 5, 0, 19);  // y = (5+0.5)*0.05 = 0.275m

  std::vector<AnchorStation> anchors;
  anchors.push_back(MakeAnchor("s_ok", 0.025, 0.275));
  // 远站点：x 与骨架重合，但 y 偏离 5.0m
  anchors.push_back(MakeAnchor("s_far", 0.5, 5.275));

  TopologyBuilderConfig config;
  config.max_snap_dist_m = 2.0;
  config.map_hash = "h3";
  config.graph_version = "v1";

  const TopologyBuildResult result =
      BuildTopologyCatalog(skeleton, map_info, anchors, config);

  EXPECT_FALSE(result.success);
  EXPECT_NE(result.error_message.find("too far"), std::string::npos)
      << "错误信息应包含 'too far'，实际：" << result.error_message;
  EXPECT_NE(result.error_message.find("s_far"), std::string::npos)
      << "错误信息应包含失败站点 id，实际：" << result.error_message;
}

// ---------------------------------------------------------------------------
// 用例 4：两个不连通走廊 -> 构建失败（disconnected）
// ---------------------------------------------------------------------------
TEST(TopologyGraphBuilderTest, DisconnectedIslands_BuildFails) {
  const MapGrid map_info = MakeMapInfo(40, 20, kResolution);
  BinaryGrid skeleton = MakeSkeleton(40, 20);
  DrawHLine(skeleton, 5, 0, 19);    // 左孤岛
  DrawHLine(skeleton, 15, 20, 39);  // 右孤岛（与左孤岛无骨架连接）

  std::vector<AnchorStation> anchors;
  anchors.push_back(MakeAnchor("s_a", 0.025, 0.275));   // 左岛
  anchors.push_back(MakeAnchor("s_b", 1.975, 0.775));   // 右岛

  TopologyBuilderConfig config;
  config.max_snap_dist_m = 2.0;
  config.map_hash = "h4";
  config.graph_version = "v1";

  const TopologyBuildResult result =
      BuildTopologyCatalog(skeleton, map_info, anchors, config);

  EXPECT_FALSE(result.success);
  EXPECT_NE(result.error_message.find("disconnected"), std::string::npos)
      << "错误信息应包含 'disconnected'，实际：" << result.error_message;
}

// ---------------------------------------------------------------------------
// 用例 5：真实折线累加长度
//   构造骨架：(0,0) -> (0,3) -> (4,3)。折线实际长度 = 3 + 4 = 7 像素。
//   在 0.05m/像素 下 = 0.35m。但用例要求 7m——改用 res=1.0m。
//   为简化测试，使用 res=1.0m 验证累加几何长度 = 7m。
// ---------------------------------------------------------------------------
TEST(TopologyGraphBuilderTest, PolylineAccumulatedLength_NotStraightLine) {
  // res = 1.0 m/px。骨架：(0,5) -> (4,5) 水平 4 像素 + (4,5) -> (4,8) 垂直
  // 3 像素，L 形折线总长度 = 4 + 3 = 7m，而起点终点直线距离 = 5m。
  const MapGrid map_info = MakeMapInfo(5, 9, 1.0);
  BinaryGrid skeleton = MakeSkeleton(5, 9);
  DrawHLine(skeleton, 5, 0, 4);
  DrawVLine(skeleton, 4, 5, 8);

  // 站点放在两端附近（世界坐标：(0,5)->(0.5,5.5)，(4,8)->(4.5,8.5)）。
  std::vector<AnchorStation> anchors;
  anchors.push_back(MakeAnchor("s_a", 0.5, 5.5));
  anchors.push_back(MakeAnchor("s_b", 4.5, 8.5));

  TopologyBuilderConfig config;
  config.max_snap_dist_m = 5.0;
  config.map_hash = "h5";
  config.graph_version = "v1";

  const TopologyBuildResult result =
      BuildTopologyCatalog(skeleton, map_info, anchors, config);

  ASSERT_TRUE(result.success) << result.error_message;

  // 找 s_a -> s_b 路径，断言其累加距离接近 7m，而非 5m 直线距离。
  const auto path =
      catalog::FindRoutePath(result.catalog, "s_a", "s_b");
  ASSERT_TRUE(path.has_value());

  // 路径距离由 catalog::EstimateRouteDistance 给出（经过中间拐角节点）。
  const auto dist =
      catalog::EstimateRouteDistance(result.catalog, "s_a", "s_b");
  ASSERT_TRUE(dist.has_value());
  // 累加长度应约等于 4 + 3 = 7m（容差 0.2m 吸收像素取整）。
  EXPECT_NEAR(*dist, 7.0, 0.2)
      << "折线累加长度应为 ~7m，实际 " << *dist << "m";

  // 至少一条边上的累加距离大于其端点直线距离（验证 polyline 累积而非
  // 直线距离）。
  bool edge_with_accumulated = false;
  for (const auto& edge : result.catalog.edges) {
    if (edge.polyline.size() >= 3) {
      // 计算折线累加长度
      double accum = 0.0;
      for (size_t i = 1; i < edge.polyline.size(); ++i) {
        const auto& p0 = edge.polyline[i - 1];
        const auto& p1 = edge.polyline[i];
        accum += std::hypot(p1.first - p0.first, p1.second - p0.second);
      }
      // 直线距离
      const auto& p_first = edge.polyline.front();
      const auto& p_last = edge.polyline.back();
      const double straight = std::hypot(p_last.first - p_first.first,
                                         p_last.second - p_first.second);
      if (accum > straight + 0.5) {
        edge_with_accumulated = true;
        break;
      }
    }
  }
  EXPECT_TRUE(edge_with_accumulated)
      << "至少一条边的折线累加长度应大于端点直线距离";
}

}  // namespace
}  // namespace amr_dispatcher_core::planning

#ifndef AMR_DISPATCHER_CORE__PLANNING__TOPOLOGY_GRAPH_BUILDER_HPP_
#define AMR_DISPATCHER_CORE__PLANNING__TOPOLOGY_GRAPH_BUILDER_HPP_

#include <string>
#include <vector>

#include "amr_dispatcher_core/catalog/station_catalog.hpp"
#include "amr_dispatcher_core/planning/map_geometry_utils.hpp"
#include "amr_dispatcher_core/planning/safety_space_filter.hpp"

namespace amr_dispatcher_core::planning {

// 业务站点锚点（来自 markers.yaml）：世界坐标 + 语义类型。
struct AnchorStation {
  std::string id;
  std::string type = "normal";  // "pickup", "dropoff", "charge", etc.
  double x = 0.0;
  double y = 0.0;
  double yaw = 0.0;
};

struct TopologyBuilderConfig {
  // 站点距离最近路网边的最大吸附允许距离（米），超过则构建失败。
  double max_snap_dist_m = 2.0;
  std::string map_hash;
  std::string graph_version = "v1";
};

struct TopologyBuildResult {
  bool success = false;
  std::string error_message;
  catalog::StationCatalog catalog;
};

// 拓扑路网构建与站点吸附边拆分。
//
// 算法流水线：
//   1. 骨架特征点提取：识别 8 邻域环连通组数 != 2 的骨架像素
//      （端点=1、分叉点>=3、孤立点=0），每个特征点生成 RoadNode。
//      纯闭合环（无特征点）任取一环上像素作为 RoadNode，避免环丢失。
//   2. 骨架链追踪：从特征点沿骨架追踪到下一特征点，生成 CatalogStationEdge，
//      polyline 保存真实折线像素序列（世界坐标），distance_m 为累加长度。
//   3. 站点吸附：将每个 AnchorStation 正交投影到最近边的 polyline，
//      距离超过 max_snap_dist_m 时报错；投影点处将原边拆分为两条子边，
//      站点作为新节点接入路网。
//   4. 连通性校验：所有站点必须处于同一连通分量（通过 FindRoutePath 验证）。
//   5. 版本标记：写入 map_hash / graph_version，最后经 ValidateStationCatalog 校验。
TopologyBuildResult BuildTopologyCatalog(
    const BinaryGrid& skeleton, const MapGrid& map_info,
    const std::vector<AnchorStation>& anchors,
    const TopologyBuilderConfig& config);

}  // namespace amr_dispatcher_core::planning

#endif  // AMR_DISPATCHER_CORE__PLANNING__TOPOLOGY_GRAPH_BUILDER_HPP_

#include "amr_dispatcher_core/planning/skeleton_extractor.hpp"

#include <cstddef>
#include <cstdint>
#include <utility>
#include <vector>

namespace amr_dispatcher_core::planning {
namespace {

// 8 邻域方向（顺时针，自正北起）：N, NE, E, SE, S, SW, W, NW。
// Zhang-Suen 的 P2..P9 与剪枝的度数统计共用这一顺序。
constexpr int kDRow[8] = {-1, -1, 0, 1, 1, 1, 0, -1};
constexpr int kDCol[8] = {0, 1, 1, 1, 0, -1, -1, -1};

// 受保护判定的欧式距离阈值（像素）：站点停靠位通常经正交投影落在骨架
// 附近，1.5 像素（默认 0.075m）容差足以吸收亚像素舍入。
constexpr double kProtectedDistancePx = 1.5;

// 对角步长：分支推进时用于把 8 方向步向量归一化，比较与来向的夹角余弦。
constexpr double kSqrt2 = 1.41421356237309504880;

// 骨架像素坐标（整数栅格）。
struct Pixel {
  int col = 0;
  int row = 0;
};

// 8 邻域内相邻骨架像素数，即剪枝算法中的"度数"。
int Degree(const BinaryGrid& grid, int col, int row) {
  int count = 0;
  for (int i = 0; i < 8; ++i) {
    if (grid.GetValue(col + kDCol[i], row + kDRow[i])) {
      ++count;
    }
  }
  return count;
}

// 8 邻域环上的连通组数（P2..P9,P2 环状序列中 0→1 跳变次数）：
//   0 = 无邻居，1 = 端点 / 单组，2 = 线段点，>= 3 = 分叉点。
// 与裸度数相比，组数不会把"紧邻正交交叉点的直线像素"（其度数也 >= 3）
// 误判为分叉，是像素骨架上更稳健的分叉判据。
int CrossingNumber(const BinaryGrid& grid, int col, int row) {
  int neighbors[8];
  int B = 0;
  for (int i = 0; i < 8; ++i) {
    neighbors[i] = grid.GetValue(col + kDCol[i], row + kDRow[i]) ? 1 : 0;
    B += neighbors[i];
  }
  if (B == 0) {
    return 0;
  }
  if (B == 8) {
    return 1;  // 完全被包围：单一连通组（防御分支，1 像素宽骨架不会出现）
  }
  int groups = 0;
  for (int i = 0; i < 8; ++i) {
    if (!neighbors[i] && neighbors[(i + 1) % 8]) {
      ++groups;
    }
  }
  return groups;
}

// 剪除分支后，停止点 S 的剩余邻居在 4 邻接（网格意义）下是否构成单一
// 连通组。成立时说明 S 仅因被剪掉的分支而呈现为"分叉"——本体是主线上的
// 冗余凸起像素（1 像素宽骨架的正交 T 接合处常见），若不一并剪除会在主干
// 上留下 1 像素毛刺伪影。真正的 Y / T / 十字分叉点剩余邻居彼此不相邻，
// 返回 false 得以保留。
bool NeighborsSingleFourConnected(const BinaryGrid& grid, int col, int row) {
  std::vector<Pixel> neighbors;
  for (int i = 0; i < 8; ++i) {
    if (grid.GetValue(col + kDCol[i], row + kDRow[i])) {
      neighbors.push_back({col + kDCol[i], row + kDRow[i]});
    }
  }
  if (neighbors.size() <= 1) {
    return true;
  }
  // 在邻居像素集合上做 4 邻接连通性 BFS。
  std::vector<uint8_t> visited(neighbors.size(), 0);
  std::vector<size_t> stack{0};
  visited[0] = 1;
  size_t reached = 1;
  while (!stack.empty()) {
    const size_t index = stack.back();
    stack.pop_back();
    for (size_t j = 0; j < neighbors.size(); ++j) {
      if (visited[j]) {
        continue;
      }
      const int dc = neighbors[index].col - neighbors[j].col;
      const int dr = neighbors[index].row - neighbors[j].row;
      if ((dc == 0 && (dr == 1 || dr == -1)) ||
          (dr == 0 && (dc == 1 || dc == -1))) {
        visited[j] = 1;
        stack.push_back(j);
        ++reached;
      }
    }
  }
  return reached == neighbors.size();
}

// 分支是否受保护：任一像素与某保护点欧式距离 < 1.5 像素即豁免。
bool IsProtectedBranch(const std::vector<Pixel>& branch,
                       const std::vector<PixelCoord>& protected_points) {
  for (const Pixel& pixel : branch) {
    for (const PixelCoord& point : protected_points) {
      const double d_col = static_cast<double>(pixel.col) - point.col;
      const double d_row = static_cast<double>(pixel.row) - point.row;
      if (d_col * d_col + d_row * d_row <
          kProtectedDistancePx * kProtectedDistancePx) {
        return true;
      }
    }
  }
  return false;
}

}  // namespace

BinaryGrid ZhangSuenThinning(const BinaryGrid& grid) {
  BinaryGrid result = grid;
  if (result.width == 0 || result.height == 0) {
    return result;
  }

  bool changed = true;
  while (changed) {
    changed = false;
    for (int step = 0; step < 2; ++step) {
      // 先收集本轮待删除像素，再统一置 0 —— 保证子步内所有判定基于同一
      // 快照（Zhang-Suen 的标准同步语义）。
      std::vector<Pixel> to_remove;
      for (uint32_t row = 0; row < result.height; ++row) {
        for (uint32_t col = 0; col < result.width; ++col) {
          const int c = static_cast<int>(col);
          const int r = static_cast<int>(row);
          if (!result.GetValue(c, r)) {
            continue;
          }
          // P2..P9（自正北顺时针），B 为邻域内骨架像素总数。
          int neighbors[8];
          int B = 0;
          for (int i = 0; i < 8; ++i) {
            neighbors[i] = result.GetValue(c + kDCol[i], r + kDRow[i]) ? 1 : 0;
            B += neighbors[i];
          }
          if (B < 2 || B > 6) {
            continue;  // 孤立点与骨架内部点均不删除
          }
          // A：P2..P9,P2 环状序列中 0→1 跳变次数，==1 保证不切断连通性。
          int A = 0;
          for (int i = 0; i < 8; ++i) {
            if (!neighbors[i] && neighbors[(i + 1) % 8]) {
              ++A;
            }
          }
          if (A != 1) {
            continue;
          }
          bool condition = false;
          if (step == 0) {
            // 子步 1：P2*P4*P6 == 0 且 P4*P6*P8 == 0
            condition = (neighbors[0] * neighbors[2] * neighbors[4] == 0) &&
                        (neighbors[2] * neighbors[4] * neighbors[6] == 0);
          } else {
            // 子步 2：P2*P4*P8 == 0 且 P2*P6*P8 == 0
            condition = (neighbors[0] * neighbors[2] * neighbors[6] == 0) &&
                        (neighbors[0] * neighbors[4] * neighbors[6] == 0);
          }
          if (condition) {
            to_remove.push_back({c, r});
          }
        }
      }
      if (!to_remove.empty()) {
        changed = true;
        for (const Pixel& pixel : to_remove) {
          result.SetValue(pixel.col, pixel.row, 0);
        }
      }
    }
  }
  return result;
}

BinaryGrid PruneSkeletonProtected(const BinaryGrid& skeleton,
                                  const std::vector<PixelCoord>& protected_points,
                                  const PruneConfig& config) {
  BinaryGrid result = skeleton;
  if (result.width == 0 || result.height == 0) {
    return result;
  }
  const double resolution = config.resolution > 0.0 ? config.resolution : 0.05;

  bool changed = true;
  while (changed) {
    changed = false;
    // 每轮重新扫描端点：上一轮剪除会改变度数，端点集合随之变化。
    for (uint32_t row = 0; row < result.height; ++row) {
      for (uint32_t col = 0; col < result.width; ++col) {
        const int start_col = static_cast<int>(col);
        const int start_row = static_cast<int>(row);
        // 端点在处理时即时复核：同一轮里它可能已被先前的剪除删除。
        if (!result.GetValue(start_col, start_row) ||
            Degree(result, start_col, start_row) != 1) {
          continue;
        }

        // 从端点向内追踪分支：visited 记录分支像素（端点起，不含停止点）。
        std::vector<Pixel> visited;
        visited.push_back({start_col, start_row});
        int prev_col = start_col;
        int prev_row = start_row;
        // 端点唯一的骨架邻居即为追踪方向。
        int cur_col = -1;
        int cur_row = -1;
        for (int i = 0; i < 8; ++i) {
          const int ncol = start_col + kDCol[i];
          const int nrow = start_row + kDRow[i];
          if (result.GetValue(ncol, nrow)) {
            cur_col = ncol;
            cur_row = nrow;
            break;
          }
        }

        bool reached_junction = false;
        bool reached_other_end = false;
        const size_t max_steps =
            static_cast<size_t>(result.width) * result.height + 1;
        while (visited.size() <= max_steps) {
          // 分叉判据用连通组数而非裸度数：紧邻正交交叉点的直线像素（如 T
          // 接合处主干上的 (15,3)）8 邻域裸度数也 >= 3，若按裸度数判定
          // 会在剪除后于主干上残留 1 像素凸起伪影。
          const int crossings = CrossingNumber(result, cur_col, cur_row);
          if (crossings >= 3) {
            reached_junction = true;
            break;
          }
          if (crossings <= 1) {
            // 追踪到另一个端点：整条线段无分叉锚点（例如孤立短线段），
            // 不属于"死胡同毛刺"，跳过不剪，避免误删整个连通分量。
            reached_other_end = true;
            break;
          }
          // 连通组数 == 2：分支中段，沿与来向最接近的方向推进。
          // 固定环序（N,NE,E,SE,S,SW,W,NW）会把"斜向紧邻的旁侧结构"排在
          // 直线延续之前（如垂直毛刺基座像素的 SE 邻居先于 S 被考察），导致
          // 追踪横向逃逸到相邻主线：毛刺因此漏剪，或整段主线被误当分支剪
          // 除。改为：
          //   1. 优先推进到本身即分叉（连通组数 >= 3）的候选 —— 命中分叉
          //      立即停止追踪（分支不含分叉点）；
          //   2. 其余候选中选与来向 (cur - prev) 夹角最小者（归一化点积最
          //      大），即直线延续优先于斜向逃逸。
          visited.push_back({cur_col, cur_row});
          const int dir_col = cur_col - prev_col;
          const int dir_row = cur_row - prev_row;
          int next_col = -1;
          int next_row = -1;
          bool next_is_junction = false;
          double next_best_cos = -2.0;
          for (int i = 0; i < 8; ++i) {
            const int ncol = cur_col + kDCol[i];
            const int nrow = cur_row + kDRow[i];
            if ((ncol == prev_col && nrow == prev_row) ||
                !result.GetValue(ncol, nrow)) {
              continue;
            }
            const int step_col = ncol - cur_col;
            const int step_row = nrow - cur_row;
            // |dir| 对所有候选为公共因子，比较 cos 时可省略；仅归一化步长。
            const double step_len =
                (step_col == 0 || step_row == 0) ? 1.0 : kSqrt2;
            const double cos_angle =
                (dir_col * step_col + dir_row * step_row) / step_len;
            const bool is_junction = CrossingNumber(result, ncol, nrow) >= 3;
            if (next_col == -1 || (is_junction && !next_is_junction) ||
                (is_junction == next_is_junction &&
                 cos_angle > next_best_cos)) {
              next_col = ncol;
              next_row = nrow;
              next_is_junction = is_junction;
              next_best_cos = cos_angle;
            }
          }
          if (next_col == -1) {
            break;  // 防御：连通组数 == 2 必有非来向邻居，不应发生。
          }
          prev_col = cur_col;
          prev_row = cur_row;
          cur_col = next_col;
          cur_row = next_row;
        }
        if (!reached_junction || reached_other_end) {
          continue;
        }

        const double branch_length_m =
            static_cast<double>(visited.size()) * resolution;
        if (!(branch_length_m < config.min_branch_length_m)) {
          continue;  // 长分支保留
        }
        // 受保护分支（承载站点）强制豁免，不可剪除。
        if (IsProtectedBranch(visited, protected_points)) {
          continue;
        }
        // 剪除短毛刺：分支像素全部置 0，分叉点保留。
        for (const Pixel& pixel : visited) {
          result.SetValue(pixel.col, pixel.row, 0);
        }
        // 冗余停止点清理：T 接合处，停止点 S 常因被剪分支才呈现为"分叉"
        // （其邻居经 4 邻接连通后实为主干线的一段）。分支剪除后 S 的剩余
        // 邻居若构成单一连通组，S 即为主干上的冗余凸起，一并剪除以免留
        // 下 1 像素伪影；真正的 Y / T / 十字分叉点剩余邻居彼此不相邻，
        // 得以保留。受保护点附近的停止点同样豁免。
        if (!IsProtectedBranch({{cur_col, cur_row}}, protected_points) &&
            NeighborsSingleFourConnected(result, cur_col, cur_row)) {
          result.SetValue(cur_col, cur_row, 0);
        }
        changed = true;
      }
    }
  }
  return result;
}

}  // namespace amr_dispatcher_core::planning

